word email.delivery-fold-step(accumulator: EmailDeliveryPlan, candidate: EmailMessage) -> EmailDeliveryPlan {
    effects none
    doc "Separate the first outbox message from the FIFO remainder."
    match accumulator.first() {
        some first => {
            emailDeliveryPlan::new(
                first = accumulator.first(),
                remaining = list::append(accumulator.remaining(), candidate))
        }
        none => {
            emailDeliveryPlan::new(
                first = option::some<EmailMessage>(candidate),
                remaining = accumulator.remaining())
        }
    }
}

word email.apply-delivery-result(store: Store, outcome: Result<Unit, BusinessError>) -> Result<Store, BusinessError> {
    effects none
    doc "Apply one explicit delivery outcome to the first queued email; failures leave Store unchanged."
    let plan = store.email-outbox().fold(
        emailDeliveryPlan::new(first = option::none<EmailMessage>(), remaining = list::empty<EmailMessage>()),
        email::delivery-fold-step);
    match plan.first() {
        none => {
            result::error<Store, BusinessError>(businessError::new(
                code = "NO_PENDING_EMAIL",
                message = "There is no queued email to deliver."))
        }
        some message => {
            match outcome {
                error provider-error => {
                    result::error<Store, BusinessError>(businessError::new(
                        code = "EMAIL_PROVIDER_FAILURE",
                        message = provider-error.message()))
                }
                ok delivered => {
                    let sent = list::append(store.sent-emails(), message);
                    let updated = store::with-email-state(store, plan.remaining(), sent);
                    result::ok<Store, BusinessError>(updated)
                }
            }
        }
    }
}

test email.delivery-fold-step/first-message {
    let message = emailMessage::new(
        to = Email::new("first@example.test"),
        subject = "First",
        body = "Body");
    let state = emailDeliveryPlan::new(
        first = option::none<EmailMessage>(),
        remaining = list::empty<EmailMessage>());
    let next = email::delivery-fold-step(state, message);
    match next.first() {
        some found => { bool::and(equals(found, message), equals(next.remaining().count(), 0)) }
        none => { false }
    }
    => true
}

test email.delivery-fold-step/later-message-appended {
    let first = emailMessage::new(
        to = Email::new("first@example.test"),
        subject = "First",
        body = "Body");
    let later = emailMessage::new(
        to = Email::new("later@example.test"),
        subject = "Later",
        body = "Body");
    let state = emailDeliveryPlan::new(
        first = option::some<EmailMessage>(first),
        remaining = list::empty<EmailMessage>());
    let next = email::delivery-fold-step(state, later);
    bool::and(
        equals(next.first(), option::some<EmailMessage>(first)),
        equals(next.remaining(), list::singleton<EmailMessage>(later)))
    => true
}

test email.apply-delivery-result/empty-outbox-precedes-provider-error {
    let failure = businessError::new(code = "DECLINED", message = "mail rejected");
    match email::apply-delivery-result(store::empty(unit), result::error<Unit, BusinessError>(failure)) {
        error problem => { equals(problem.code(), "NO_PENDING_EMAIL") }
        ok updated => { false }
    }
    => true
}

test email.apply-delivery-result/provider-failure-retains-fifo-state {
    let first = emailMessage::new(to = Email::new("first@example.test"), subject = "First", body = "First body");
    let later = emailMessage::new(to = Email::new("later@example.test"), subject = "Later", body = "Later body");
    let initial = store::with-email-state(
        store::empty(unit),
        list::append(list::singleton<EmailMessage>(first), later),
        list::empty<EmailMessage>());
    match email::apply-delivery-result(
        initial,
        result::error<Unit, BusinessError>(businessError::new(code = "TEMPORARY", message = "mail gateway unavailable"))) {
        error problem => {
            bool::and(
                equals(problem.code(), "EMAIL_PROVIDER_FAILURE"),
                bool::and(
                    equals(problem.message(), "mail gateway unavailable"),
                    bool::and(equals(initial.email-outbox(), list::append(list::singleton<EmailMessage>(first), later)), equals(initial.sent-emails().count(), 0))))
        }
        ok updated => { false }
    }
    => true
}

test email.apply-delivery-result/success-moves-only-first-message {
    let first = emailMessage::new(to = Email::new("first@example.test"), subject = "First", body = "First body");
    let later = emailMessage::new(to = Email::new("later@example.test"), subject = "Later", body = "Later body");
    let prior-sent = emailMessage::new(to = Email::new("sent@example.test"), subject = "Sent", body = "Sent body");
    let initial = store::with-email-state(
        store::empty(unit),
        list::append(list::singleton<EmailMessage>(first), later),
        list::singleton<EmailMessage>(prior-sent));
    match email::apply-delivery-result(initial, result::ok<Unit, BusinessError>(unit)) {
        error problem => { false }
        ok updated => {
            bool::and(
                equals(updated.email-outbox(), list::singleton<EmailMessage>(later)),
                bool::and(
                    equals(updated.sent-emails(), list::append(list::singleton<EmailMessage>(prior-sent), first)),
                    bool::and(
                        equals(updated.customers(), initial.customers()),
                        bool::and(
                            equals(updated.products(), initial.products()),
                            bool::and(
                                equals(updated.subscriptions(), initial.subscriptions()),
                                bool::and(equals(updated.invoices(), initial.invoices()), equals(updated.payments(), initial.payments())))))))
        }
    }
    => true
}

example email.apply-delivery-result/empty-outbox {
    match email::apply-delivery-result(store::empty(unit), result::ok<Unit, BusinessError>(unit)) {
        error problem => { problem.code() }
        ok updated => { "unexpected" }
    }
    => "NO_PENDING_EMAIL"
}
